Here are a few simple JavaScript examples that retrieve information from a local `countries.json` file.  
You can use the version that matches your project setup.

## Example `countries.json`

```json
[
  {
    "name": "Nepal",
    "capital": "Kathmandu",
    "population": 30000000,
    "region": "Asia"
  },
  {
    "name": "Japan",
    "capital": "Tokyo",
    "population": 125000000,
    "region": "Asia"
  },
  {
    "name": "France",
    "capital": "Paris",
    "population": 68000000,
    "region": "Europe"
  }
]
```

## Browser JavaScript using `fetch`

Use this if `countries.json` is in the same folder as your HTML file.

```html
<!DOCTYPE html>
<html>
<head>
  <title>Countries Info</title>
</head>
<body>
  <h1>Countries</h1>
  <div id="countries"></div>

  <script>
    fetch("countries.json")
      .then(response => {
        if (!response.ok) {
          throw new Error("Could not load countries.json");
        }
        return response.json();
      })
      .then(countries => {
        const container = document.getElementById("countries");

        countries.forEach(country => {
          const div = document.createElement("div");

          div.innerHTML = `
            <h2>${country.name}</h2>
            <p>Capital: ${country.capital}</p>
            <p>Population: ${country.population}</p>
            <p>Region: ${country.region}</p>
          `;

          container.appendChild(div);
        });
      })
      .catch(error => {
        console.error("Error:", error);
      });
  </script>
</body>
</html>
```

## JavaScript function to get one country by name

```javascript
async function getCountryByName(countryName) {
  try {
    const response = await fetch("countries.json");

    if (!response.ok) {
      throw new Error("Could not load countries.json");
    }

    const countries = await response.json();

    const country = countries.find(
      item => item.name.toLowerCase() === countryName.toLowerCase()
    );

    if (!country) {
      console.log("Country not found");
      return null;
    }

    console.log(country);
    return country;
  } catch (error) {
    console.error("Error loading country data:", error);
  }
}

getCountryByName("Nepal");
```

## Node.js version

Use this if you are running JavaScript with Node.js.

```javascript
const fs = require("fs");

fs.readFile("countries.json", "utf8", (error, data) => {
  if (error) {
    console.error("Error reading file:", error);
    return;
  }

  try {
    const countries = JSON.parse(data);

    countries.forEach(country => {
      console.log(`Name: ${country.name}`);
      console.log(`Capital: ${country.capital}`);
      console.log(`Population: ${country.population}`);
      console.log(`Region: ${country.region}`);
      console.log("-------------------");
    });
  } catch (parseError) {
    console.error("Error parsing JSON:", parseError);
  }
});
```

If you are using the browser version, remember that `fetch("countries.json")` usually needs to be run through a local server, not by directly opening the HTML file.

